INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N040-01','CN0290','S040-01','建设时间与规模','2024-10-24公告','2024-06-06开工；10-23生产楼封顶；排水沟完成80%，31单体中27开工、11封顶；计划2026Q2试产不等于实际。','WEB_COMPANY','公开正文摘录/转述，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N040-02','CN0290','S040-02','后续建设线索','2025-10政府调研','政府调研项目，不代表验收或投产。','WEB_PRIMARY','公开正文摘录/转述，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N040-03','CN0290','S040-08','设计设施','行业报道','报道项目总投资约10亿元、反应器/离心机/冷凝器及废物处理配套；未证明污水站单元顺序及规格。','WEB_SECONDARY','公开正文摘录/转述，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N040-04','CN0291','S040-03','项目投资与自用','2026-04-25公告','4月23日董事会；总投资10500万元、固定资产8500万元；计划2026年6月开始、工期9个月；供大洋及子公司自用。非污水投资和实际建设。','WEB_COMPANY','公开正文摘录/转述，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N040-05','CN0291','S040-04','共享站两阶段','3.3.2、3.3.3.3.4','报告现有四公司共享500m³/d站：厌氧生化、混凝沉淀、A/O、膜；扩建设计800m³/d，膜分离能力800m³/d；水解酸化、EGSB、A/O、沉淀、SBR、混凝沉淀、膜分离。4000m³事故池、双氧水区1000m³池为容积非水量。膜类型及实际扩建、催化剂接入待核；截图失败，依据正文。','WEB_PRIMARY','公开正文摘录/转述，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N040-06','CN0243','S040-05','共享站负荷与阶段矛盾','6.2.2 pp192–195','设计高浓水5.5t/d、低浓水103.2t/d、合计108.7t/d；生化设计120m³/d。文中另述120t/d已建未验收，另段称在建，不能强认现行；已批其他租户44.894t/d、余量75.106t/d非实测。初雨进站、事故池2500m³；在线监控未超标系报告历史叙述，非催化剂实测；截图未成。','WEB_COMPANY','公开正文摘录/转述，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N040-07','CN0243','S040-05','中试废水边界','6.2.2 pp192–195','POE聚合物中试3.39t/d、1129.760t/a；分股1.3514、0.720、1.32t/d之和3.3914，舍入差。高浓水先高级氧化，再与低浓、生活混合，混凝沉淀、水解酸化、一级A/O、MBR替代二沉；纳园区后排海；污泥压滤外运。未核2026催化剂线接入。','WEB_COMPANY','公开正文摘录/转述，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N040-08','CN0031','S040-06','中试站设计与异口径','表2.3-1、5.2.2 p174、表3.9-1','生产/储区初雨及生产生活水进站、办公雨水直排；12m³/d，事故/初雨池1000m³。预蒸馏、双效蒸发、催化微电解、高级氧化、调节水解、UASB、接触氧化；园区站处理后园区回用。表2.3-1简写预处理+接触氧化；5.2.2为细化。3411.99t/a和3510.99m³/a并存，不换算；污泥6.7t/a、废盐145.55t/a、前后馏残液697.38t/a为固废/废液口径，不计水量。截图超时。','WEB_COMPANY','公开正文摘录/转述，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N040-09','CN0048','S040-07','厂址产能及产废','2024-05-22表1–3','2003成立、占地约28000m²、注册资本6400万美元、800万只/a产能；贵金属溶液制备→氧化铝/稀土粉加水制浆→陶瓷载体涂覆→干燥焙烧。中间品危废40t/a，半固态，非污水；成分Al2O3 47.5%、ZrO2 22%、TiO2 12.5%、Pd 2%、Pt 0.1%、Rh 0.05%，原表部分成分重复列名，不自行加总；拟转移至石嘴山铂唯（许可HW50 10000t/a），非实际转移量。未披露废水处理；截图跳转，正文可用。','WEB_COMPANY','公开正文摘录/转述，非原件归档','2026-11-28');
